        "gap": "lg"
      },
      "children": [
        "section_1_card",
        "section_2_card",
        "section_3_card",
        "section_4_card",
        "section_5_card"
      ]
    },
    "section_1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "section_1_header_stack",
        "section_1_text"
      ]
    },
    "section_1_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "section_1_icon",
        "section_1_title"
      ]
    },
    "section_1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000252_01_1_thermometer-half.svg"
      },
      "children": []
    },
    "section_1_title": {
      "type": "Text",
      "props": {
        "text": "Understanding First-Degree Burns",
        "variant": "h2"
      },
      "children": []
    },
    "section_1_text": {
      "type": "Text",
      "props": {
        "text": "A first-degree burn is a minor burn that affects only the outermost layer of skin (epidermis). It typically causes pain, redness, and mild swelling. These burns usually heal within a week without scarring.",
        "variant": "body"
      },
      "children": []
    },
    "section_2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "section_2_header_stack",
        "section_2_intro_text",
        "section_2_list_stack"
      ]
    },
    "section_2_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "section_2_icon",
        "section_2_title"
      ]
    },
    "section_2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000252_01_2_info-circle.svg"
      },
      "children": []
    },
    "section_2_title": {
      "type": "Text",
      "props": {
        "text": "Recognizing Minor Burn Symptoms",
        "variant": "h2"
      },
      "children": []
    },
    "section_2_intro_text": {
      "type": "Text",
      "props": {
        "text": "Common signs of a first-degree burn include:",
        "variant": "body"
      },
      "children": []
    },
    "section_2_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "section_2_list_item_1",
        "section_2_list_item_2",
        "section_2_list_item_3",
        "section_2_list_item_4"
      ]
    },
    "section_2_list_item_1": {
      "type": "Text",
      "props": {
        "text": "• Redness: The skin in the affected area will appear red.",
        "variant": "body"
      },
      "children": []
    },
    "section_2_list_item_2": {
      "type": "Text",
      "props": {
        "text": "• Pain: The burn will be painful to the touch.",
        "variant": "body"
      },
      "children": []
    },
    "section_2_list_item_3": {
      "type": "Text",
      "props": {
        "text": "• Mild Swelling: Slight puffiness may be present.",
        "variant": "body"
      },
      "children": []
    },
    "section_2_list_item_4": {
      "type": "Text",
      "props": {
        "text": "• Dry Skin: The skin will remain dry and will not blister.",
        "variant": "body"
      },
      "children": []
    },
    "section_3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "section_3_header_stack",
        "section_3_intro_text",
        "section_3_list_stack"
      ]
    },
    "section_3_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "section_3_icon",
        "section_3_title"
      ]
    },
    "section_3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000252_01_3_first-aid-kit.svg"
      },
      "children": []
    },
    "section_3_title": {
      "type": "Text",
      "props": {
        "text": "Immediate First-Aid for Minor Burns",
        "variant": "h2"
      },
      "children": []
    },
    "section_3_intro_text": {
      "type": "Text",
      "props": {
        "text": "Follow these steps for immediate care of a first-degree burn:",
        "variant": "body"
      },
      "children": []
    },
    "section_3_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "section_3_list_item_1",
        "section_3_list_item_2",
        "section_3_list_item_3",
        "section_3_list_item_4",
        "section_3_list_item_5"
      ]
    },
    "section_3_list_item_1": {
      "type": "Text",
      "props": {
        "text": "1. Cool the Burn: Hold the burned area under cool (not cold) running water for 10-20 minutes, or apply cool, wet compresses. Do not use ice, as it can further damage the skin.",
        "variant": "body"
      },
      "children": []
    },
    "section_3_list_item_2": {
      "type": "Text",
      "props": {
        "text": "2. Remove Constrictive Items: Gently remove any rings, watches, belts, or other tight items from the burned area before swelling begins.",
        "variant": "body"
      },
      "children": []
    },
    "section_3_list_item_3": {
      "type": "Text",
      "props": {
        "text": "3. Cover the Burn: Once cooled, loosely cover the burn with a sterile, non-adhesive bandage or a clean cloth. This protects the area and helps prevent infection. Do not apply butter, oil, or home remedies.",
        "variant": "body"
      },
      "children": []
    },
    "section_3_list_item_4": {
      "type": "Text",
      "props": {
        "text": "4. Pain Relief: Over-the-counter pain relievers like ibuprofen or acetaminophen can help manage pain and reduce swelling.",
        "variant": "body"
      },
      "children": []
    },
    "section_3_list_item_5": {
      "type": "Text",
      "props": {
        "text": "5. Moisturize: After the burn has cooled, you can apply a moisturizing lotion, aloe vera gel, or a burn cream to keep the skin hydrated and promote healing.",
        "variant": "body"
      },
      "children": []
    },
    "section_4_card": {
      "type": "Card",
      "props": {},
      "children": [
        "section_4_header_stack",
        "section_4_intro_text",
        "section_4_list_stack"
      ]
    },
    "section_4_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "section_4_icon",
        "section_4_title"
      ]
    },
    "section_4_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000252_01_4_hospital.svg"
      },
      "children": []
    },
    "section_4_title": {
      "type": "Text",
      "props": {
        "text": "When to Seek Medical Attention",
        "variant": "h2"
      },
      "children": []
    },
    "section_4_intro_text": {
      "type": "Text",
      "props": {
        "text": "While most first-degree burns can be treated at home, seek medical attention if:",
        "variant": "body"
      },
      "children": []
    },
    "section_4_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "section_4_list_item_1",
        "section_4_list_item_2",
        "section_4_list_item_3",
        "section_4_list_item_4",
        "section_4_list_item_5",
        "section_4_list_item_6"
      ]
    },
    "section_4_list_item_1": {
      "type": "Text",
      "props": {
        "text": "• The burn is larger than 3 inches (7.5 cm) in diameter.",
        "variant": "body"
      },
      "children": []
    },
    "section_4_list_item_2": {
      "type": "Text",
      "props": {
        "text": "• The burn is on the face, hands, feet, major joints, or genitals.",
        "variant": "body"
      },
      "children": []
    },
    "section_4_list_item_3": {
      "type": "Text",
      "props": {
        "text": "• The pain is severe and not relieved by over-the-counter medication.",
        "variant": "body"
      },
      "children": []
    },
    "section_4_list_item_4": {
      "type": "Text",
      "props": {
        "text": "• You notice signs of infection, such as increased redness, swelling, pus, or fever.",
        "variant": "body"
      },
      "children": []
    },
    "section_4_list_item_5": {
      "type": "Text",
      "props": {
        "text": "• The burn develops blisters (indicating a second-degree burn).",
        "variant": "body"
      },
      "children": []
    },
    "section_4_list_item_6": {
      "type": "Text",
      "props": {
        "text": "• You are unsure about the severity of the burn or how to treat it.",
        "variant": "body"
      },
      "children": []
    },
    "section_5_card": {
      "type": "Card",
      "props": {},
      "children": [
        "section_5_header_stack",
        "section_5_intro_text",
        "section_5_list_stack"
      ]
    },
    "section_5_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "section_5_icon",
        "section_5_title"
      ]
    },
    "section_5_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000252_01_5_shield-fill.svg"
      },
      "children": []
    },
    "section_5_title": {
      "type": "Text",
      "props": {
        "text": "Preventing Burns",
        "variant": "h2"
      },
      "children": []
    },
    "section_5_intro_text": {
      "type": "Text",
      "props": {
        "text": "Taking simple precautions can help prevent burns:",
        "variant": "body"
      },
      "children": []
    },
    "section_5_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "section_5_list_item_1",
        "section_5_list_item_2",
        "section_5_list_item_3",
        "section_5_list_item_4",
        "section_5_list_item_5"
      ]
    },
    "section_5_list_item_1": {
      "type": "Text",
      "props": {
        "text": "• Keep hot liquids and food away from the edges of counters and tables.",
        "variant": "body"
      },
      "children": []
    },
    "section_5_list_item_2": {
      "type": "Text",
      "props": {
        "text": "• Never leave cooking food unattended.",
        "variant": "body"
      },
      "children": []
    },
    "section_5_list_item_3": {
      "type": "Text",
      "props": {
        "text": "• Test bathwater temperature before getting in.",
        "variant": "body"
      },
      "children": []
    },
    "section_5_list_item_4": {
      "type": "Text",
      "props": {
        "text": "• Keep matches, lighters, and chemicals out of reach of children.",
        "variant": "body"
      },
      "children": []
    },
    "section_5_list_item_5": {
      "type": "Text",
      "props": {
        "text": "• Install smoke detectors and check them regularly.",
        "variant": "body"
      },
      "children": []
    }
  }
}
